// 24-S3 acceptance: a tab's queue against the real commit path, in a
// throwaway PostgreSQL schema. The client's confirmed state matches the
// server's; a lost acknowledgment and a re-sent journal apply once; a
// refusal leaves the authoritative state; Publish is pinned to the version
// the queue settled at. Do not edit this file to match an implementation.
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, it, vi } from 'vitest';
import type { Prisma } from '@prisma/client';
import { createGrid, withLetter, type Grid } from '@/engine/grid';
import { serializeGrid, type SerializedGrid } from '@/lib/puzzle-storage';
import { createTestDatabase, type TestDatabase } from '@/test-support/database';
import type { PuzzleContent } from './apply';
import { commitPuzzleOperation } from './commit';
import type { Operation } from './operation';
import { projectOutbox } from './outbox';
import { publishPuzzleAt } from './publish';
import { OperationQueue, type QueueDeps } from './queue';

let db: TestDatabase;
beforeAll(async () => {
  db = await createTestDatabase();
  await db.client.user.create({ data: { id: 'adam', name: 'Adam', email: 'adam@queue.example.test', displayName: 'Adam' } });
}, 60_000);
afterAll(async () => { await db?.drop(); });

function letters(grid: Grid, entries: Array<[number, number, string]>): Grid {
  return entries.reduce((next, [col, row, letter]) => withLetter(next, { col, row }, letter), grid);
}
const start = letters(createGrid({ cols: 3, rows: 3 }), [[0, 0, 'C'], [1, 0, 'A'], [2, 0, 'T']]);

async function seed(): Promise<{ id: string; content: PuzzleContent }> {
  const content: PuzzleContent = { grid: serializeGrid(start), hints: {}, title: 'Queue', phase: 'grid' };
  const { id } = await db.client.puzzle.create({
    data: { builderId: 'adam', title: content.title, grid: content.grid as unknown as Prisma.InputJsonValue, hints: {}, phase: 'grid' },
  });
  return { id, content };
}
async function server(id: string) {
  const row = await db.client.puzzle.findUniqueOrThrow({ where: { id } });
  return {
    content: { grid: row.grid as unknown as SerializedGrid, hints: row.hints as Record<string, string>, title: row.title, phase: row.phase } as PuzzleContent,
    version: row.version, resetEpoch: row.resetEpoch, publishedAt: row.publishedAt,
  };
}
function tab(id: string, content: PuzzleContent, version = 0, deps: Partial<QueueDeps> = {}) {
  const refused = vi.fn();
  const queue = new OperationQueue(
    { confirmed: { content, version, resetEpoch: 0 }, pending: [] },
    { puzzleId: id, clientId: `tab-${randomUUID().slice(0, 8)}`, newOpId: randomUUID },
    { send: (op) => commitPuzzleOperation(db.client, 'adam', op), onRefused: refused, retryDelaysMs: [5], ...deps },
  );
  return { queue, refused };
}

describe('24-S3-12 a tab’s queue on the commit path', () => {
  it('commits a session of every kind in order; the confirmed state is the server’s', async () => {
    const { id, content } = await seed();
    const { queue } = tab(id, content);
    queue.add({ kind: 'cells', writes: [{ col: 0, row: 1, value: 'A' }, { col: 0, row: 2, value: 'B' }] });
    queue.add({ kind: 'lock', word: { col: 0, row: 0, orientation: 'across', length: 3 } });
    queue.add({ kind: 'title', title: ' Renamed ' });
    queue.add({ kind: 'cells', writes: [{ col: 1, row: 1, value: 'R' }, { col: 1, row: 2, value: 'E' }, { col: 2, row: 1, value: 'E' }, { col: 2, row: 2, value: 'D' }] });
    queue.add({ kind: 'enterHints' });
    queue.add({ kind: 'hint', key: '1-across', text: 'Pet' });
    await queue.whenIdle();
    const stored = await server(id);
    expect(stored.version).toBe(6);
    expect(queue.outbox).toEqual({ confirmed: { content: stored.content, version: 6, resetEpoch: 0 }, pending: [] });
    expect(stored.content.title).toBe('Renamed');
    expect(stored.content.hints['1-across']).toBe('Pet');
  });

  it('a Start Over moves the tab into the new epoch, and its next edits are accepted', async () => {
    const { id, content } = await seed();
    const { queue, refused } = tab(id, content);
    queue.add({ kind: 'startOver', keepLockedWords: false });
    const after = queue.add({ kind: 'cells', writes: [{ col: 2, row: 2, value: 'Z' }] });
    expect(after.epoch).toBe(1);
    await queue.whenIdle();
    expect(refused).not.toHaveBeenCalled();
    const stored = await server(id);
    expect(stored).toMatchObject({ version: 2, resetEpoch: 1 });
    expect(queue.outbox.confirmed).toEqual({ content: stored.content, version: 2, resetEpoch: 1 });
  });

  it('a lost acknowledgment is retried with its opId and applied once; a re-sent journal changes nothing', async () => {
    const { id, content } = await seed();
    let lose = true;
    const sent: Operation[] = [];
    const { queue } = tab(id, content, 0, {
      send: async (op) => {
        sent.push(op);
        const outcome = await commitPuzzleOperation(db.client, 'adam', op);
        if (lose) { lose = false; throw new Error('response lost'); }
        return outcome;
      },
    });
    const op = queue.add({ kind: 'cells', writes: [{ col: 2, row: 2, value: 'X' }] });
    queue.add({ kind: 'cells', writes: [{ col: 2, row: 2, value: 'Y' }] });
    await queue.whenIdle();
    expect(sent.map((o) => o.opId).filter((o) => o === op.opId)).toHaveLength(2);
    expect((await server(id)).version).toBe(2);
    expect(await db.client.puzzleOperation.count({ where: { puzzleId: id } })).toBe(2);

    // The next page opens at version 2 and re-sends the journaled first one.
    const stored = await server(id);
    const next = tab(id, stored.content, stored.version);
    next.queue.adopt([op]);
    await next.queue.whenIdle();
    expect(await next.queue.settled(op.opId)).toEqual({ status: 'accepted', version: 1 });
    expect(next.queue.outbox.confirmed).toEqual({ content: stored.content, version: 2, resetEpoch: 0 });
    expect((await server(id)).version).toBe(2);
  });

  it('a burst into a word another tab locked is refused whole; the projection is the server’s', async () => {
    const { id, content } = await seed();
    await commitPuzzleOperation(db.client, 'adam', {
      opId: randomUUID(), puzzleId: id, clientId: 'other', epoch: 0, baseVersion: 0, kind: 'lock',
      word: { col: 0, row: 0, orientation: 'across', length: 3 },
    });
    const { queue, refused } = tab(id, content);
    queue.add({ kind: 'cells', writes: [{ col: 0, row: 0, value: 'B' }, { col: 0, row: 1, value: 'E' }] });
    await queue.whenIdle();
    expect(refused).toHaveBeenCalledTimes(1);
    expect(refused.mock.calls[0][1]).toBe('locked');
    expect(projectOutbox(queue.outbox).content.grid.cells[0][0]).toEqual({ kind: 'active', letter: 'C' });
    expect((await server(id)).version).toBe(1);
  });

  it('publishing at the version the queue settled publishes; a commit from elsewhere since makes it stale', async () => {
    for (const interfere of [false, true]) {
      const { id, content } = await seed();
      const { queue } = tab(id, content);
      queue.add({ kind: 'enterHints' });
      const last = queue.add({ kind: 'title', title: 'Ready' });
      await queue.whenIdle();
      const keys = Object.keys(queue.outbox.confirmed.content.hints);
      for (const key of keys) queue.add({ kind: 'hint', key, text: `Clue ${key}` });
      await queue.whenIdle();
      const settledAt = queue.outbox.confirmed.version;
      expect(await queue.settled(last.opId)).toEqual({ status: 'accepted', version: 2 });
      if (interfere) {
        await commitPuzzleOperation(db.client, 'adam', {
          opId: randomUUID(), puzzleId: id, clientId: 'other', epoch: 0, baseVersion: settledAt, kind: 'title', title: 'Elsewhere',
        });
      }
      const outcome = await publishPuzzleAt(db.client, 'adam', { puzzleId: id, version: settledAt, visibility: 'public' });
      expect(outcome.status).toBe(interfere ? 'refused' : 'published');
      if (interfere) expect(outcome).toEqual({ status: 'refused', code: 'stale' });
      expect((await server(id)).publishedAt === null).toBe(interfere);
    }
  });
});
